1	// acceptance.mjs —— 验收执行器：把里程碑的可证伪验收标准逐条判一遍，并触发状态流转闭环。
2	// 三条铁律：
3	//   ① 只判判得了的：check.type 支持 file-exists（文件在不在）、file-contains
4	//      （文件在、含指定关键词、字数达标）、command（真跑一条命令、按退出码/输出定过不过——
5	//      把「机器可判」从文件级升到行为级：真跑测试、真发请求，验得出行为缺陷）；
6	//      不认识的类型当场报错，绝不瞎猜；
7	//   ② 先判后写：评判全程只读文件，判出结论才动状态——评判中途出错（标准写坏、
8	//      路径越狱等）时 .opc/ 一个字都不会变；
9	//   ③ 结论驱动流转：全过 → 里程碑 verifying→done；有败 → verifying→failed，
10	//      失败计数和三振熔断由状态机（statemachine.mjs）自动记，本文件不重复实现。
11	// 人判条目（manual:true）标 needs-inspector：脚本不代人定案，不写结论也不动状态，
12	// 由 tick 剧本拉起独立检察会话、经 write verdict 回填后再走流转（MVP 假团队不含人判条目）。
13	// 本文件对 .opc/ 的读写全部经 store，绝不直接碰 .opc/ 的文件系统。
14	
15	import { spawnSync } from 'node:child_process';
16	import fs from 'node:fs/promises';
17	import path from 'node:path';
18	import { WRITE_TYPES, MACHINE_CHECK_TYPES } from './schemas.mjs';
19	import { readJson, writeJson } from './store.mjs';
20	import { advance } from './statemachine.mjs';
21	import { fileApproval, findArtifactReviewForClaim, markReviewConsumed } from './approvals.mjs';
22	import { listArtifacts } from './artifact.mjs';
23	
24	// 机器可判的 check 类型全集：唯一出处已挪到 schemas.mjs（phase1-milestones 写入校验要用，
25	// 而 schemas.mjs 是无环底座、不能反过来 import 本文件）。这里原样转出，precheck.mjs
26	// 继续从本文件 import 不必改，新增机器可判类型只改 schemas.mjs 那一处。
27	export { MACHINE_CHECK_TYPES };
28	
29	// 里程碑清单的存放位置以写入类型表声明的为准，不另抄一份路径字面量。
30	const MILESTONES_REL = WRITE_TYPES['phase1-milestones'].path();
31	
32	// 交付物路径清洗：验收标准里的 path 是相对项目根的路径（deliverables/ 在 .opc/ 之外），
33	// 只能老老实实待在项目根里面——绝对路径、.. 逃逸一律拒收，防止验收标准被人写成探针去读别处。
34	// field 是报错里点名的字段（默认 check.path；command 型的 cwd 复用同一套清洗，只是换个名头报错）。
35	function deliverablePath(root, relPath, where, field = 'check.path') {
36	  if (typeof relPath !== 'string' || relPath.trim() === '') {
37	    throw new Error(`${where}的 ${field} 必须是非空文字（相对项目根的路径）`);
38	  }
39	  const normalized = path.normalize(relPath);
40	  if (path.isAbsolute(normalized) || normalized === '..' || normalized.startsWith(`..${path.sep}`)) {
41	    throw new Error(`${where}的 ${field}「${relPath}」试图逃出项目根，拒绝评判`);
42	  }
43	  return path.join(root, normalized);
44	}
45	
46	// 读交付物文本：文件不在返回 null（这是正常败因），其余错误原样上抛不吞。
47	async function readDeliverable(file) {
48	  try {
49	    return await fs.readFile(file, 'utf8');
50	  } catch (err) {
51	    if (err.code === 'ENOENT') return null;
52	    throw err;
53	  }
54	}
55	
56	// 取一段文本的尾 n 字（失败信息里带关键输出用）：短了原样返回，长了截尾并标「…」。
57	function tail(text, n = 200) {
58	  const s = String(text ?? '');
59	  return s.length <= n ? s : `…${s.slice(-n)}`;
60	}
61	
62	// 判一条 command 型验收标准：真跑一条命令，按退出码（可选 stdout 关键字）定过不过。
63	// 这是把「机器可判」从文件级（在不在、含不含词）升到行为级（真跑测试、真发请求）的关键。
64	// 形状（cmd 非空数组、期望码/超时/关键字类型）写坏＝配置错误，当场抛错（不算「不过」）；
65	// cwd 逃出项目根同样抛错（照 deliverablePath 先例）；命令真跑出来的坏结果（退出码不符、
66	// 超时、缺关键字、可执行文件找不到）才算「不过」，白话点名败因并带关键输出尾。
67	function judgeCommand(root, check, where) {
68	  // —— 形状先验（配置错误 → 抛错）——
69	  if (
70	    !Array.isArray(check.cmd) ||
71	    check.cmd.length === 0 ||
72	    check.cmd.some((a) => typeof a !== 'string' || a === '')
73	  ) {
74	    throw new Error(`${where}的 check.cmd 必须是非空文字的数组（argv：命令＋参数逐个一格，cmd[0] 建议 node）`);
75	  }
76	  if ('expect_exit' in check && !Number.isInteger(check.expect_exit)) {
77	    throw new Error(`${where}的 check.expect_exit 必须是整数（期望退出码）`);
78	  }
79	  if ('timeout_ms' in check && (!Number.isInteger(check.timeout_ms) || check.timeout_ms <= 0)) {
80	    throw new Error(`${where}的 check.timeout_ms 必须是正整数（毫秒）`);
81	  }
82	  if ('expect_stdout_contains' in check && (typeof check.expect_stdout_contains !== 'string' || check.expect_stdout_contains === '')) {
83	    throw new Error(`${where}的 check.expect_stdout_contains 必须是非空文字`);
84	  }
85	  // cwd 归一化后必须落在项目根内（防 ../ 逃逸）；不写默认在项目根跑。
86	  const cwd = check.cwd === undefined ? root : deliverablePath(root, check.cwd, where, 'check.cwd');
87	  const expectExit = 'expect_exit' in check ? check.expect_exit : 0;
88	  const timeoutMs = 'timeout_ms' in check ? check.timeout_ms : 30000;
89	
90	  const r = spawnSync(check.cmd[0], check.cmd.slice(1), {
91	    cwd,
92	    timeout: timeoutMs,
93	    maxBuffer: 16 * 1024 * 1024, // 16MB：输出再大也不至于半路截断把判据判花
94	    encoding: 'utf8'
95	  });
96	
97	  // —— 真跑出来的坏结果 → 不过（白话点名）——
98	  if (r.error) {
99	    if (r.error.code === 'ETIMEDOUT') {
100	      return { ok: false, reason: `命令超时（超过 ${timeoutMs}ms 未跑完，判不过）：${check.cmd.join(' ')}` };
101	    }
102	    if (r.error.code === 'ENOENT') {
103	      return { ok: false, reason: `命令跑不起来：找不到可执行文件「${check.cmd[0]}」（cmd[0] 建议用 node）` };
104	    }
105	    return { ok: false, reason: `命令执行出错（${r.error.code ?? r.error.message}）：${check.cmd.join(' ')}` };
106	  }
107	  const stdout = r.stdout ?? '';
108	  const stderr = r.stderr ?? '';
109	  if (r.status !== expectExit) {
110	    const outTail = tail(stdout || stderr);
111	    return {
112	      ok: false,
113	      reason: `命令退出码 ${r.status}，期望 ${expectExit}` + (outTail ? `；关键输出尾：${outTail}` : '')
114	    };
115	  }
116	  if ('expect_stdout_contains' in check && !stdout.includes(check.expect_stdout_contains)) {
117	    return {
118	      ok: false,
119	      reason: `命令输出里缺关键字「${check.expect_stdout_contains}」；关键输出尾：${tail(stdout)}`
120	    };
121	  }
122	  return { ok: true, reason: '' };
123	}
124	
125	// 判一条程序可判的验收标准，返回 {ok, reason}。判不了（标准本身写坏）就抛错。
126	async function judgeCheck(root, check, where) {
127	  if (typeof check.type !== 'string') {
128	    throw new Error(`${where}的 check 缺 type，没法评判`);
129	  }
130	
131	  // command 型不认 check.path（它跑命令、不读单个交付物文件），先它一步分流，
132	  // 免得被下面按文件路径清洗的那步误拦。
133	  if (check.type === 'command') {
134	    return judgeCommand(root, check, where);
135	  }
136	
137	  const file = deliverablePath(root, check.path, where);
138	
139	  if (check.type === 'file-exists') {
140	    const text = await readDeliverable(file);
141	    if (text === null) return { ok: false, reason: `找不到文件 ${check.path}` };
142	    return { ok: true, reason: '' };
143	  }
144	
145	  if (check.type === 'file-contains') {
146	    // 可选参数先验形状：写坏的标准是配置错误，当场报错，不算「不过」。
147	    if ('keywords' in check) {
148	      if (!Array.isArray(check.keywords) || check.keywords.some((k) => typeof k !== 'string' || k === '')) {
149	        throw new Error(`${where}的 check.keywords 必须是非空文字的数组`);
150	      }
151	    }
152	    if ('min_chars' in check && (!Number.isInteger(check.min_chars) || check.min_chars <= 0)) {
153	      throw new Error(`${where}的 check.min_chars 必须是正整数`);
154	    }
155	    const text = await readDeliverable(file);
156	    if (text === null) return { ok: false, reason: `找不到文件 ${check.path}` };
157	    for (const keyword of check.keywords ?? []) {
158	      if (!text.includes(keyword)) {
159	        return { ok: false, reason: `${check.path} 里缺关键词「${keyword}」` };
160	      }
161	    }
162	    if (Number.isInteger(check.min_chars) && text.length < check.min_chars) {
163	      return { ok: false, reason: `${check.path} 字数不足：只有 ${text.length} 字，要求至少 ${check.min_chars} 字` };
164	    }
165	    return { ok: true, reason: '' };
166	  }
167	
168	  throw new Error(`${where}的 check.type「${check.type}」不认识，目前只会判 file-exists、file-contains 和 command`);
169	}
170	
171	// 验收总入口。返回 {pass, failed, needs_inspector, incident}：
172	//   pass=true  全过，里程碑已推到 done；
173	//   pass=false 有败，failed[] 逐条点名败因，里程碑已推到 failed（计数/三振由状态机管）；
174	//   pass=null  程序判的全过但还有人判条目没回填，不定案、不动状态，needs_inspector[] 列出待检条目。
175	export async function runAcceptance(root, milestoneId, { actor = '脚本' } = {}) {
176	  const milestones = await readJson(root, MILESTONES_REL);
177	  if (!Array.isArray(milestones)) {
178	    throw new Error(`还没有里程碑清单（${MILESTONES_REL}），没法验收`);
179	  }
180	  const entry = milestones.find((m) => m.id === milestoneId);
181	  if (!entry) {
182	    throw new Error(`里程碑清单里找不到「${milestoneId}」，没法验收`);
183	  }
184	  const status = entry.status ?? 'planned'; // 没写过状态的里程碑就是刚排期的
185	  if (status === 'done' || status === 'voided') {
186	    throw new Error(`里程碑「${milestoneId}」已经是「${status}」，终态不再验收`);
187	  }
188	  // 验收只发生在「团队自称完成」与「老板验收」之间：没申报就没得验。
189	  if (!Number.isInteger(entry.claimed_at_tick)) {
190	    throw new Error(`里程碑「${milestoneId}」还没申报完成（缺 claimed_at_tick），先经 write milestone-claim 申报再验收`);
191	  }
192	
193	  // —— 评判段：纯读，一个字都不写。——
194	  const failed = [];
195	  const checked = [];
196	  const needsInspector = [];
197	  for (const [i, criterion] of entry.criteria.entries()) {
198	    const where = `里程碑 ${milestoneId} 第 ${i + 1} 条验收标准`;
199	    if (criterion.manual === true) {
200	      needsInspector.push({ index: i, desc: criterion.desc });
201	      continue;
202	    }
203	    const { ok, reason } = await judgeCheck(root, criterion.check, where);
204	    checked.push({ index: i, desc: criterion.desc, ok, ...(ok ? {} : { reason }) });
205	    if (!ok) failed.push({ index: i, desc: criterion.desc, reason });
206	  }
207	
208	  // 程序判的全过、但有人判条目没回填：不定案。检察会话回填 verdict 之前，状态原地不动。
209	  if (failed.length === 0 && needsInspector.length > 0) {
210	    return { pass: null, failed: [], needs_inspector: needsInspector, incident: false };
211	  }
212	
213	  // —— 评审门（review_required）——
214	  // 机器标准全过、也没有待 AI 检察的人判条目，但这个里程碑定义了「要老板亲自评审」：不由脚本径直定 done，
215	  // 改挂/认一张 artifact-review 评审单，按老板的准入/打回定案。与 needs_inspector（AI 检察员）彻底分家——
216	  // 这里返回独立的 awaiting_review 信号（pass 仍是 null 但 needs_inspector 为空），fire/剧本据此暂停等老板、
217	  // 绝不拉 AI 检察员。approved→落到下面的 pass 回路推 done（advance 硬闸此时放行）；rejected→把打回意见
218	  // 转成一条失败项，落到下面的 failed 回路（里程碑 failed+needs_fix，precheck 下轮当 defect 直奔去修）。
219	  // 两种里程碑要过评审门：定义时声明 review_required 的；以及被老板报过问题、这一轮修完需复审的
220	  //（review_after_fix，老板规则：打回/报问题＝我要再看，准入+意见＝别烦我）。
221	  let approvedReviewId = null; // 凭哪张单放行的；推完 done 再盖消费戳（盖早了硬闸会把自己拦下）
222	  if (failed.length === 0 && (entry.review_required === true || entry.review_after_fix === true)) {
223	    const review = await findArtifactReviewForClaim(root, milestoneId, entry.claimed_at_tick);
224	    if (review === null || (review.status ?? 'pending') === 'pending') {
225	      // 送验收（planned/failed→verifying），让里程碑在评审期间显示「验收中/待评审」；已在 verifying 不重复推。
226	      if (status !== 'verifying') {
227	        await advance(root, 'milestone', milestoneId, 'verifying', { actor });
228	      }
229	      let approvalId;
230	      let artifactId;
231	      if (review === null) {
232	        // 头一回走到评审门：挂一张评审单，绑本里程碑的主产出（source=milestone/<编号>）。
233	        const requiredSource = `milestone/${milestoneId}`;
234	        const artifact = (await listArtifacts(root)).find((a) => a.source === requiredSource);
235	        if (artifact === undefined) {
236	          // review_required 蕴含 artifact_required、claim 闸已保证主产出在册；查无＝档案对不上，喊停不猜。
237	          throw new Error(
238	            `里程碑「${milestoneId}」要评审却找不到主产出（画廊里没有 source=${requiredSource} 的 artifact），` +
239	              '档案对不上（review_required 本应蕴含 artifact_required + claim 闸兜底），停手等人查'
240	          );
241	        }
242	        const filed = await fileApproval(root, {
243	          type: 'artifact-review',
244	          kind: 'artifact-review',
245	          title: `请老板试用并评审产出：${typeof artifact.title === 'string' ? artifact.title : milestoneId}`,
246	          artifactId: artifact.id,
247	          milestone: milestoneId,
248	          requestedBy: actor,
249	          tick: entry.claimed_at_tick
250	        });
251	        approvalId = filed.id;
252	        artifactId = artifact.id;
253	      } else {
254	        // 已挂单、老板还没拍板：原地继续等（幂等，绝不重复挂单）。
255	        approvalId = review.id;
256	        artifactId = review.artifact_id;
257	      }
258	      return {
259	        pass: null,
260	        failed: [],
261	        needs_inspector: [],
262	        awaiting_review: { approval: approvalId, artifact_id: artifactId, milestone: milestoneId },
263	        incident: false
264	      };
265	    }
266	    if ((review.status ?? 'pending') === 'rejected') {
267	      // 老板打回：把打回意见转成一条失败项，走下面的 failed 回路。
268	      const note = review.decision?.note;
269	      failed.push({
270	        index: -1,
271	        desc: `老板评审打回产出（评审单 ${review.id}）`,
272	        reason: typeof note === 'string' && note.trim() !== '' ? note.trim() : '（老板未留具体意见）'
273	      });
274	    }
275	    if ((review.status ?? 'pending') === 'approved') {
276	      approvedReviewId = review.id; // 准入：落到下面的 pass 回路推 done，推完再盖消费戳
277	    }
278	  }
279	
280	  // —— 落账段：结论已定，才开始动状态。——
281	  const pass = failed.length === 0;
282	
283	  // 送验收：planned/failed 的里程碑先推到 verifying（走状态机，留流转脚印）。
284	  if (status !== 'verifying') {
285	    await advance(root, 'milestone', milestoneId, 'verifying', { actor });
286	  }
287	
288	  // 验收结论入册（追加进对应里程碑的 verdicts[]，形状以写入类型表的校验器为准），
289	  // 并顺手清掉申报标记——不清的话，预检会把没返工的活当成又申报了一次，验收就会空转。
290	  const verdict = {
291	    milestone: milestoneId,
292	    pass,
293	    failed,
294	    checked,
295	    claimed_at_tick: entry.claimed_at_tick, // 留档：这份结论判的是哪一次申报
296	    at: new Date().toISOString()
297	  };
298	  WRITE_TYPES['verdict'].validate(verdict);
299	  const fresh = await readJson(root, MILESTONES_REL); // advance 刚改过清单，重读再改，不拿旧底稿覆盖
300	  const freshEntry = fresh.find((m) => m.id === milestoneId);
301	  if (!freshEntry) {
302	    throw new Error(`里程碑「${milestoneId}」在写结论前从清单里消失了，账目异常，停手等人查`);
303	  }
304	  if (!Array.isArray(freshEntry.verdicts)) freshEntry.verdicts = [];
305	  freshEntry.verdicts.push(verdict);
306	  delete freshEntry.claimed_at_tick;
307	  // 复审义务只管这一轮：过了就销标（下次要复审得由新的报问题重新置）。不过不销——还欠一次复审。
308	  if (pass) delete freshEntry.review_after_fix;
309	  await writeJson(root, MILESTONES_REL, fresh, {
310	    actor,
311	    event: `验收结论:${milestoneId}:${pass ? '过' : '不过'}`
312	  });
313	
314	  // 状态流转由脚本读结论触发：过 → done；不过 → failed（失败计数与三振熔断在状态机里）。
315	  const result = await advance(root, 'milestone', milestoneId, pass ? 'done' : 'failed', { actor });
316	
317	  // 放行用掉的那张准入单盖消费戳：之后它顶不了下一轮的门（老板报问题重开、修完要复审时，
318	  // 旧准入单不许把新一轮悄悄放行）。必须在 advance 之后——之前盖会让硬闸查不到未消费的单、
319	  // 把这次正当的收官自己拦下。
320	  if (pass && approvedReviewId !== null) {
321	    await markReviewConsumed(root, approvedReviewId, entry.claimed_at_tick);
322	  }
323	
324	  return { pass, failed, needs_inspector: [], incident: result.incident };
325	}
