// acceptance.mjs —— 验收执行器：把里程碑的可证伪验收标准逐条判一遍，并触发状态流转闭环。
// 三条铁律：
//   ① 只判判得了的：check.type 支持 file-exists（文件在不在）、file-contains
//      （文件在、含指定关键词、字数达标）、command（真跑一条命令、按退出码/输出定过不过——
//      把「机器可判」从文件级升到行为级：真跑测试、真发请求，验得出行为缺陷）；
//      不认识的类型当场报错，绝不瞎猜；
//   ② 先判后写：评判全程只读文件，判出结论才动状态——评判中途出错（标准写坏、
//      路径越狱等）时 .opc/ 一个字都不会变；
//   ③ 结论驱动流转：全过 → 里程碑 verifying→done；有败 → verifying→failed，
//      失败计数和三振熔断由状态机（statemachine.mjs）自动记，本文件不重复实现。
// 人判条目（manual:true）标 needs-inspector：脚本不代人定案，不写结论也不动状态，
// 由 tick 剧本拉起独立检察会话、经 write verdict 回填后再走流转（MVP 假团队不含人判条目）。
// 本文件对 .opc/ 的读写全部经 store，绝不直接碰 .opc/ 的文件系统。

import { spawnSync } from 'node:child_process';
import fs from 'node:fs/promises';
import path from 'node:path';
import { WRITE_TYPES, MACHINE_CHECK_TYPES } from './schemas.mjs';
import { readJson, writeJson } from './store.mjs';
import { advance } from './statemachine.mjs';
import { fileApproval, findArtifactReviewForClaim, markReviewConsumed } from './approvals.mjs';
import { listArtifacts } from './artifact.mjs';

// 机器可判的 check 类型全集：唯一出处已挪到 schemas.mjs（phase1-milestones 写入校验要用，
// 而 schemas.mjs 是无环底座、不能反过来 import 本文件）。这里原样转出，precheck.mjs
// 继续从本文件 import 不必改，新增机器可判类型只改 schemas.mjs 那一处。
export { MACHINE_CHECK_TYPES };

// 里程碑清单的存放位置以写入类型表声明的为准，不另抄一份路径字面量。
const MILESTONES_REL = WRITE_TYPES['phase1-milestones'].path();

// 交付物路径清洗：验收标准里的 path 是相对项目根的路径（deliverables/ 在 .opc/ 之外），
// 只能老老实实待在项目根里面——绝对路径、.. 逃逸一律拒收，防止验收标准被人写成探针去读别处。
// field 是报错里点名的字段（默认 check.path；command 型的 cwd 复用同一套清洗，只是换个名头报错）。
function deliverablePath(root, relPath, where, field = 'check.path') {
  if (typeof relPath !== 'string' || relPath.trim() === '') {
    throw new Error(`${where}的 ${field} 必须是非空文字（相对项目根的路径）`);
  }
  const normalized = path.normalize(relPath);
  if (path.isAbsolute(normalized) || normalized === '..' || normalized.startsWith(`..${path.sep}`)) {
    throw new Error(`${where}的 ${field}「${relPath}」试图逃出项目根，拒绝评判`);
  }
  return path.join(root, normalized);
}

// 读交付物文本：文件不在返回 null（这是正常败因），其余错误原样上抛不吞。
async function readDeliverable(file) {
  try {
    return await fs.readFile(file, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return null;
    throw err;
  }
}

// 取一段文本的尾 n 字（失败信息里带关键输出用）：短了原样返回，长了截尾并标「…」。
function tail(text, n = 200) {
  const s = String(text ?? '');
  return s.length <= n ? s : `…${s.slice(-n)}`;
}

// 判一条 command 型验收标准：真跑一条命令，按退出码（可选 stdout 关键字）定过不过。
// 这是把「机器可判」从文件级（在不在、含不含词）升到行为级（真跑测试、真发请求）的关键。
// 形状（cmd 非空数组、期望码/超时/关键字类型）写坏＝配置错误，当场抛错（不算「不过」）；
// cwd 逃出项目根同样抛错（照 deliverablePath 先例）；命令真跑出来的坏结果（退出码不符、
// 超时、缺关键字、可执行文件找不到）才算「不过」，白话点名败因并带关键输出尾。
function judgeCommand(root, check, where) {
  // —— 形状先验（配置错误 → 抛错）——
  if (
    !Array.isArray(check.cmd) ||
    check.cmd.length === 0 ||
    check.cmd.some((a) => typeof a !== 'string' || a === '')
  ) {
    throw new Error(`${where}的 check.cmd 必须是非空文字的数组（argv：命令＋参数逐个一格，cmd[0] 建议 node）`);
  }
  if ('expect_exit' in check && !Number.isInteger(check.expect_exit)) {
    throw new Error(`${where}的 check.expect_exit 必须是整数（期望退出码）`);
  }
  if ('timeout_ms' in check && (!Number.isInteger(check.timeout_ms) || check.timeout_ms <= 0)) {
    throw new Error(`${where}的 check.timeout_ms 必须是正整数（毫秒）`);
  }
  if ('expect_stdout_contains' in check && (typeof check.expect_stdout_contains !== 'string' || check.expect_stdout_contains === '')) {
    throw new Error(`${where}的 check.expect_stdout_contains 必须是非空文字`);
  }
  // cwd 归一化后必须落在项目根内（防 ../ 逃逸）；不写默认在项目根跑。
  const cwd = check.cwd === undefined ? root : deliverablePath(root, check.cwd, where, 'check.cwd');
  const expectExit = 'expect_exit' in check ? check.expect_exit : 0;
  const timeoutMs = 'timeout_ms' in check ? check.timeout_ms : 30000;

  const r = spawnSync(check.cmd[0], check.cmd.slice(1), {
    cwd,
    timeout: timeoutMs,
    maxBuffer: 16 * 1024 * 1024, // 16MB：输出再大也不至于半路截断把判据判花
    encoding: 'utf8'
  });

  // —— 真跑出来的坏结果 → 不过（白话点名）——
  if (r.error) {
    if (r.error.code === 'ETIMEDOUT') {
      return { ok: false, reason: `命令超时（超过 ${timeoutMs}ms 未跑完，判不过）：${check.cmd.join(' ')}` };
    }
    if (r.error.code === 'ENOENT') {
      return { ok: false, reason: `命令跑不起来：找不到可执行文件「${check.cmd[0]}」（cmd[0] 建议用 node）` };
    }
    return { ok: false, reason: `命令执行出错（${r.error.code ?? r.error.message}）：${check.cmd.join(' ')}` };
  }
  const stdout = r.stdout ?? '';
  const stderr = r.stderr ?? '';
  if (r.status !== expectExit) {
    const outTail = tail(stdout || stderr);
    return {
      ok: false,
      reason: `命令退出码 ${r.status}，期望 ${expectExit}` + (outTail ? `；关键输出尾：${outTail}` : '')
    };
  }
  if ('expect_stdout_contains' in check && !stdout.includes(check.expect_stdout_contains)) {
    return {
      ok: false,
      reason: `命令输出里缺关键字「${check.expect_stdout_contains}」；关键输出尾：${tail(stdout)}`
    };
  }
  return { ok: true, reason: '' };
}

// 判一条程序可判的验收标准，返回 {ok, reason}。判不了（标准本身写坏）就抛错。
async function judgeCheck(root, check, where) {
  if (typeof check.type !== 'string') {
    throw new Error(`${where}的 check 缺 type，没法评判`);
  }

  // command 型不认 check.path（它跑命令、不读单个交付物文件），先它一步分流，
  // 免得被下面按文件路径清洗的那步误拦。
  if (check.type === 'command') {
    return judgeCommand(root, check, where);
  }

  const file = deliverablePath(root, check.path, where);

  if (check.type === 'file-exists') {
    const text = await readDeliverable(file);
    if (text === null) return { ok: false, reason: `找不到文件 ${check.path}` };
    return { ok: true, reason: '' };
  }

  if (check.type === 'file-contains') {
    // 可选参数先验形状：写坏的标准是配置错误，当场报错，不算「不过」。
    if ('keywords' in check) {
      if (!Array.isArray(check.keywords) || check.keywords.some((k) => typeof k !== 'string' || k === '')) {
        throw new Error(`${where}的 check.keywords 必须是非空文字的数组`);
      }
    }
    if ('min_chars' in check && (!Number.isInteger(check.min_chars) || check.min_chars <= 0)) {
      throw new Error(`${where}的 check.min_chars 必须是正整数`);
    }
    const text = await readDeliverable(file);
    if (text === null) return { ok: false, reason: `找不到文件 ${check.path}` };
    for (const keyword of check.keywords ?? []) {
      if (!text.includes(keyword)) {
        return { ok: false, reason: `${check.path} 里缺关键词「${keyword}」` };
      }
    }
    if (Number.isInteger(check.min_chars) && text.length < check.min_chars) {
      return { ok: false, reason: `${check.path} 字数不足：只有 ${text.length} 字，要求至少 ${check.min_chars} 字` };
    }
    return { ok: true, reason: '' };
  }

  throw new Error(`${where}的 check.type「${check.type}」不认识，目前只会判 file-exists、file-contains 和 command`);
}

// 验收总入口。返回 {pass, failed, needs_inspector, incident}：
//   pass=true  全过，里程碑已推到 done；
//   pass=false 有败，failed[] 逐条点名败因，里程碑已推到 failed（计数/三振由状态机管）；
//   pass=null  程序判的全过但还有人判条目没回填，不定案、不动状态，needs_inspector[] 列出待检条目。
export async function runAcceptance(root, milestoneId, { actor = '脚本' } = {}) {
  const milestones = await readJson(root, MILESTONES_REL);
  if (!Array.isArray(milestones)) {
    throw new Error(`还没有里程碑清单（${MILESTONES_REL}），没法验收`);
  }
  const entry = milestones.find((m) => m.id === milestoneId);
  if (!entry) {
    throw new Error(`里程碑清单里找不到「${milestoneId}」，没法验收`);
  }
  const status = entry.status ?? 'planned'; // 没写过状态的里程碑就是刚排期的
  if (status === 'done' || status === 'voided') {
    throw new Error(`里程碑「${milestoneId}」已经是「${status}」，终态不再验收`);
  }
  // 验收只发生在「团队自称完成」与「老板验收」之间：没申报就没得验。
  if (!Number.isInteger(entry.claimed_at_tick)) {
    throw new Error(`里程碑「${milestoneId}」还没申报完成（缺 claimed_at_tick），先经 write milestone-claim 申报再验收`);
  }

  // —— 评判段：纯读，一个字都不写。——
  const failed = [];
  const checked = [];
  const needsInspector = [];
  for (const [i, criterion] of entry.criteria.entries()) {
    const where = `里程碑 ${milestoneId} 第 ${i + 1} 条验收标准`;
    if (criterion.manual === true) {
      needsInspector.push({ index: i, desc: criterion.desc });
      continue;
    }
    const { ok, reason } = await judgeCheck(root, criterion.check, where);
    checked.push({ index: i, desc: criterion.desc, ok, ...(ok ? {} : { reason }) });
    if (!ok) failed.push({ index: i, desc: criterion.desc, reason });
  }

  // 程序判的全过、但有人判条目没回填：不定案。检察会话回填 verdict 之前，状态原地不动。
  if (failed.length === 0 && needsInspector.length > 0) {
    return { pass: null, failed: [], needs_inspector: needsInspector, incident: false };
  }

  // —— 评审门（review_required）——
  // 机器标准全过、也没有待 AI 检察的人判条目，但这个里程碑定义了「要老板亲自评审」：不由脚本径直定 done，
  // 改挂/认一张 artifact-review 评审单，按老板的准入/打回定案。与 needs_inspector（AI 检察员）彻底分家——
  // 这里返回独立的 awaiting_review 信号（pass 仍是 null 但 needs_inspector 为空），fire/剧本据此暂停等老板、
  // 绝不拉 AI 检察员。approved→落到下面的 pass 回路推 done（advance 硬闸此时放行）；rejected→把打回意见
  // 转成一条失败项，落到下面的 failed 回路（里程碑 failed+needs_fix，precheck 下轮当 defect 直奔去修）。
  // 两种里程碑要过评审门：定义时声明 review_required 的；以及被老板报过问题、这一轮修完需复审的
  //（review_after_fix，老板规则：打回/报问题＝我要再看，准入+意见＝别烦我）。
  let approvedReviewId = null; // 凭哪张单放行的；推完 done 再盖消费戳（盖早了硬闸会把自己拦下）
  if (failed.length === 0 && (entry.review_required === true || entry.review_after_fix === true)) {
    const review = await findArtifactReviewForClaim(root, milestoneId, entry.claimed_at_tick);
    if (review === null || (review.status ?? 'pending') === 'pending') {
      // 送验收（planned/failed→verifying），让里程碑在评审期间显示「验收中/待评审」；已在 verifying 不重复推。
      if (status !== 'verifying') {
        await advance(root, 'milestone', milestoneId, 'verifying', { actor });
      }
      let approvalId;
      let artifactId;
      if (review === null) {
        // 头一回走到评审门：挂一张评审单，绑本里程碑的主产出（source=milestone/<编号>）。
        const requiredSource = `milestone/${milestoneId}`;
        const artifact = (await listArtifacts(root)).find((a) => a.source === requiredSource);
        if (artifact === undefined) {
          // review_required 蕴含 artifact_required、claim 闸已保证主产出在册；查无＝档案对不上，喊停不猜。
          throw new Error(
            `里程碑「${milestoneId}」要评审却找不到主产出（画廊里没有 source=${requiredSource} 的 artifact），` +
              '档案对不上（review_required 本应蕴含 artifact_required + claim 闸兜底），停手等人查'
          );
        }
        const filed = await fileApproval(root, {
          type: 'artifact-review',
          kind: 'artifact-review',
          title: `请老板试用并评审产出：${typeof artifact.title === 'string' ? artifact.title : milestoneId}`,
          artifactId: artifact.id,
          milestone: milestoneId,
          requestedBy: actor,
          tick: entry.claimed_at_tick
        });
        approvalId = filed.id;
        artifactId = artifact.id;
      } else {
        // 已挂单、老板还没拍板：原地继续等（幂等，绝不重复挂单）。
        approvalId = review.id;
        artifactId = review.artifact_id;
      }
      return {
        pass: null,
        failed: [],
        needs_inspector: [],
        awaiting_review: { approval: approvalId, artifact_id: artifactId, milestone: milestoneId },
        incident: false
      };
    }
    if ((review.status ?? 'pending') === 'rejected') {
      // 老板打回：把打回意见转成一条失败项，走下面的 failed 回路。
      const note = review.decision?.note;
      failed.push({
        index: -1,
        desc: `老板评审打回产出（评审单 ${review.id}）`,
        reason: typeof note === 'string' && note.trim() !== '' ? note.trim() : '（老板未留具体意见）'
      });
    }
    if ((review.status ?? 'pending') === 'approved') {
      approvedReviewId = review.id; // 准入：落到下面的 pass 回路推 done，推完再盖消费戳
    }
  }

  // —— 落账段：结论已定，才开始动状态。——
  const pass = failed.length === 0;

  // 送验收：planned/failed 的里程碑先推到 verifying（走状态机，留流转脚印）。
  if (status !== 'verifying') {
    await advance(root, 'milestone', milestoneId, 'verifying', { actor });
  }

  // 验收结论入册（追加进对应里程碑的 verdicts[]，形状以写入类型表的校验器为准），
  // 并顺手清掉申报标记——不清的话，预检会把没返工的活当成又申报了一次，验收就会空转。
  const verdict = {
    milestone: milestoneId,
    pass,
    failed,
    checked,
    claimed_at_tick: entry.claimed_at_tick, // 留档：这份结论判的是哪一次申报
    at: new Date().toISOString()
  };
  WRITE_TYPES['verdict'].validate(verdict);
  const fresh = await readJson(root, MILESTONES_REL); // advance 刚改过清单，重读再改，不拿旧底稿覆盖
  const freshEntry = fresh.find((m) => m.id === milestoneId);
  if (!freshEntry) {
    throw new Error(`里程碑「${milestoneId}」在写结论前从清单里消失了，账目异常，停手等人查`);
  }
  if (!Array.isArray(freshEntry.verdicts)) freshEntry.verdicts = [];
  freshEntry.verdicts.push(verdict);
  delete freshEntry.claimed_at_tick;
  // 复审义务只管这一轮：过了就销标（下次要复审得由新的报问题重新置）。不过不销——还欠一次复审。
  if (pass) delete freshEntry.review_after_fix;
  await writeJson(root, MILESTONES_REL, fresh, {
    actor,
    event: `验收结论:${milestoneId}:${pass ? '过' : '不过'}`
  });

  // 状态流转由脚本读结论触发：过 → done；不过 → failed（失败计数与三振熔断在状态机里）。
  const result = await advance(root, 'milestone', milestoneId, pass ? 'done' : 'failed', { actor });

  // 放行用掉的那张准入单盖消费戳：之后它顶不了下一轮的门（老板报问题重开、修完要复审时，
  // 旧准入单不许把新一轮悄悄放行）。必须在 advance 之后——之前盖会让硬闸查不到未消费的单、
  // 把这次正当的收官自己拦下。
  if (pass && approvedReviewId !== null) {
    await markReviewConsumed(root, approvedReviewId, entry.claimed_at_tick);
  }

  return { pass, failed, needs_inspector: [], incident: result.incident };
}

