150	// tick 收尾三连（原子执行，中途任何一步喊停都不放锁——锁留在原地就是「这轮没收好尾」的记号）：
151	//   ① 验明身份：锁在、代数对；读草稿，缺叙述或缺下轮计划直接喊停；
152	//   ② 落 tick 正式档（action、起止时间、耗时秒、决定、产出、status:'finished'、本轮结局）；
153	//   ③ 渲染汇报（三栏齐才出）→ 存档 reports/<seq>.md → 放锁。
154	// 返回 {seq, status, exit, markdown, reportRel}，exit 由本轮结局映射（CLI 原样照办）。
155	export async function tickEnd(root, { generation, status, action = null } = {}) {
156	  if (!Number.isInteger(generation)) {
157	    throw new Error('tick-end 需要整数代数（tick-begin 发的 --gen）');
158	  }
159	  const exit = exitForStatus(status); // 结局先验明：坏 status 在动任何档案之前就喊停
160	  if (action !== null && (typeof action !== 'string' || action.trim() === '')) {
161	    throw new Error('action（本轮主动作）要么不带，要么是非空文字');
162	  }
163	
164	  const lock = await readLock(root);
165	  if (lock === null) {
166	    throw new Error('锁已不存在，没法收尾——这轮多半已被接管或已经收过尾');
167	  }
168	  if (lock.generation !== generation) {
169	    throw new Error(`代数不符：现在的锁是第 ${lock.generation} 代，你报的第 ${generation} 代已经过时，收尾被拒`);
170	  }
171	  const seq = lock.tick_seq;
172	  if (!Number.isInteger(seq) || seq <= 0) {
173	    throw new Error('锁文件里的轮次序号不像话，没法收尾');
174	  }
175	  const startedAt = lock.holder?.started_at;
176	  if (typeof startedAt !== 'string' || startedAt.trim() === '') {
177	    throw new Error('锁文件缺开工时间，耗时算不出来，没法收尾');
178	  }
179	
180	  const draft = await readJson(root, PATHS.tickDraft(seq));
181	  if (draft === null) {
182	    throw new Error(`第 ${seq} 轮还没有草稿，先 write tick-field 提交 narrative（叙述）和 next_plan（下轮计划）再收尾`);
183	  }
184	  if (typeof draft.narrative !== 'string' || draft.narrative.trim() === '') {
185	    throw new Error(`第 ${seq} 轮草稿缺 narrative（叙述），不许收尾`);
186	  }
187	  if (typeof draft.next_plan !== 'string' || draft.next_plan.trim() === '') {
188	    throw new Error(`第 ${seq} 轮草稿缺 next_plan（下轮计划），空计划不许收尾`);
189	  }
190	
191	  const endedAt = new Date().toISOString();
192	  const record = {
193	    seq,
194	    status: 'finished', // 轮次生命周期的终态（started→finished）；中止（aborted）由接管方补记
195	    result: status, // 本轮结局（映射退出码的那个词），留档供 audit 还原
196	    action,
197	    started_at: startedAt,
198	    ended_at: endedAt,
199	    duration_seconds: durationBetween(startedAt, endedAt),
200	    decisions: Array.isArray(draft.decisions) ? draft.decisions : [],
201	    outputs: Array.isArray(draft.outputs) ? draft.outputs : [],
202	    // 本轮产出对应的 artifact id 列表：与 outputs（string[] 的产出说明）正交，供 hub 跨引 artifact 画廊。
203	    artifacts: Array.isArray(draft.artifacts) ? draft.artifacts : [],
204	    generation
205	  };
