207	    actor: '脚本',
208	    event: `tick-end：第 ${seq} 轮收尾（第 ${generation} 代）`
209	  });
210	
211	  const markdown = await render(root, seq);
212	  await writeText(root, PATHS.report(seq), markdown, { actor: '脚本', event: `汇报存档：第 ${seq} 轮` });
213	  await release(root, generation);
214	
215	  return { seq, status, exit, markdown, reportRel: PATHS.report(seq) };
216	}
