// 三栏按 REPORT_COLUMNS 的顺序出，任何一栏凑不齐数据就抛错——不出残缺汇报。
export async function render(root, seq) {
  if (!Number.isInteger(seq) || seq <= 0) {
    throw new Error('汇报需要正整数的轮次序号');
  }
  opcDir(root); // 项目没初始化就在这里报错

  const draft = await readJson(root, PATHS.tickDraft(seq));
  await ingestPending(root); // 保住原「花费栏」的入账副作用：账照入（只是不在汇报里显），账本保持当前

  // 三栏的内容各自备好；键与 REPORT_COLUMNS 的 key 一一对应。
  const sections = {
    work_items: buildWorkItems(draft, seq),
    outputs: buildOutputs(draft),
    next_plan: buildNextPlan(draft, seq)
  };

  const parts = [`# 第 ${seq} 轮汇报`];
  REPORT_COLUMNS.forEach((col, i) => {
    const lines = sections[col.key];
    if (!Array.isArray(lines) || lines.length === 0) {
      // REPORT_COLUMNS 加了新栏而这里没跟上时，宁可当场报错也不出缺栏的汇报
      throw new Error(`汇报栏「${col.name}」还没有渲染实现，缺栏即报错，不出残缺汇报`);
    }
    parts.push(`## ${i + 1}. ${col.name}`, lines.join('\n'));
  });
  return parts.join('\n\n') + '\n';
}

