  }
  const exit = exitForStatus(status); // 结局先验明：坏 status 在动任何档案之前就喊停
  if (action !== null && (typeof action !== 'string' || action.trim() === '')) {
    throw new Error('action（本轮主动作）要么不带，要么是非空文字');
  }

  const lock = await readLock(root);
  if (lock === null) {
    throw new Error('锁已不存在，没法收尾——这轮多半已被接管或已经收过尾');
  }
  if (lock.generation !== generation) {
    throw new Error(`代数不符：现在的锁是第 ${lock.generation} 代，你报的第 ${generation} 代已经过时，收尾被拒`);
  }
  const seq = lock.tick_seq;
  if (!Number.isInteger(seq) || seq <= 0) {
    throw new Error('锁文件里的轮次序号不像话，没法收尾');
  }
  const startedAt = lock.holder?.started_at;
  if (typeof startedAt !== 'string' || startedAt.trim() === '') {
    throw new Error('锁文件缺开工时间，耗时算不出来，没法收尾');
  }

  const draft = await readJson(root, PATHS.tickDraft(seq));
  if (draft === null) {
    throw new Error(`第 ${seq} 轮还没有草稿，先 write tick-field 提交 narrative（叙述）和 next_plan（下轮计划）再收尾`);
  }
  if (typeof draft.narrative !== 'string' || draft.narrative.trim() === '') {
    throw new Error(`第 ${seq} 轮草稿缺 narrative（叙述），不许收尾`);
  }
  if (typeof draft.next_plan !== 'string' || draft.next_plan.trim() === '') {
    throw new Error(`第 ${seq} 轮草稿缺 next_plan（下轮计划），空计划不许收尾`);
  }

  const endedAt = new Date().toISOString();
  const record = {
    seq,
    status: 'finished', // 轮次生命周期的终态（started→finished）；中止（aborted）由接管方补记
    result: status, // 本轮结局（映射退出码的那个词），留档供 audit 还原
    action,
    started_at: startedAt,
    ended_at: endedAt,
    duration_seconds: durationBetween(startedAt, endedAt),
    decisions: Array.isArray(draft.decisions) ? draft.decisions : [],
    outputs: Array.isArray(draft.outputs) ? draft.outputs : [],
    // 本轮产出对应的 artifact id 列表：与 outputs（string[] 的产出说明）正交，供 hub 跨引 artifact 画廊。
    artifacts: Array.isArray(draft.artifacts) ? draft.artifacts : [],
    generation
  };
  await writeJson(root, PATHS.tick(seq), record, {
    actor: '脚本',
    event: `tick-end：第 ${seq} 轮收尾（第 ${generation} 代）`
  });

  const markdown = await render(root, seq);
  await writeText(root, PATHS.report(seq), markdown, { actor: '脚本', event: `汇报存档：第 ${seq} 轮` });
  await release(root, generation);

  return { seq, status, exit, markdown, reportRel: PATHS.report(seq) };
}

